func TestReleaseStateCutoffSelectsHistoricalCurrentAndResolvesInRange(t *testing.T) {
	router := newTestRouter(t)
	db := openStateStore(t)
	registerEnvironmentOK(t, router, "prod")
	createRecordOK(t, router, stateRecordBody("prod", "1.0.0", "allowed", "1.0.0"))
	v1 := createRecordOK(t, router, stateV1Body)
	createRecordOK(t, router, stateV2Body)

	atV1 := v1["recorded_at"].(string)
	body := fetchReleaseState(t, router,
		"/api/v1/environments/prod/release-state?as_of="+atV1)
	state := body
	if state["as_of"] != atV1 {
		t.Fatalf("as_of = %v, want echoed %s", state["as_of"], atV1)
	}
	current := state["current_release"].(map[string]any)
	if current["version"] != "1.1.0" {
		t.Fatalf("cutoff current = %v, want 1.1.0 (1.2.0 not yet recorded)", current["version"])
	}
	previous := state["previous_release"].(map[string]any)
	if previous["version"] != "1.0.0" {
		t.Fatalf("cutoff previous = %v, want 1.0.0", previous["version"])
